def 获取规则库(预编译: bool = True) -> list:
    """返回全部 115 条审计规则，可选预编译正则。"""
    if not 预编译:
        return [dict(r) for r in _原始规则]
    规则列表 = []
    for r in _原始规则:
        规则 = dict(r)
        try:
            规则["编译模式"] = re.compile(r["模式"])
        except re.error:
            规则["编译模式"] = None
        规则列表.append(规则)
    return 规则列表


